INSERT INTO `landing_pages` (`id`, `user_id`, `template_id`, `title`, `slug`, `data`, `domain`, `status`, `expires_at`, `created_at`, `updated_at`) VALUES ('15', '1', '10', 'test2', 'dag1', '{\"site.title\":\"DAG!\",\"header.name\":\"OriginD\",\"menu.about\":null,\"menu.work\":null,\"menu.contact\":null,\"hero.badge\":\"DAG\",\"hero.name\":\"OriginD\",\"hero.subtitle\":\"M\\u1ed9t ng\\u01b0\\u1eddi \\u0111a ng\\u00e0nh \\u2022 \\u0110am m\\u00ea s\\u00e1ng t\\u1ea1o \\u2022 Lu\\u00f4n h\\u1ecdc h\\u1ecfi\",\"hero.profile_image\":\"https:\\/\\/phukiennillkin.com\\/wp-content\\/uploads\\/2026\\/03\\/anh-girl-xinh-14.jpg\",\"about.title\":\"V\\u1ec1 t\\u00f4i\",\"about.description\":\"T\\u00f4i l\\u00e0 m\\u1ed9t ng\\u01b0\\u1eddi h\\u1ecdc h\\u1ecfi kh\\u00f4ng ng\\u1eebng v\\u00e0 \\u0111am m\\u00ea bi\\u1ebfn \\u00fd t\\u01b0\\u1edfng th\\u00e0nh hi\\u1ec7n th\\u1ef1c.\\n                        V\\u1edbi n\\u1ec1n t\\u1ea3ng \\u0111a ng\\u00e0nh, t\\u00f4i c\\u00f3 kh\\u1ea3 n\\u0103ng th\\u00edch \\u1ee9ng nhanh v\\u00e0 mang l\\u1ea1i g\\u00f3c nh\\u00ecn m\\u1edbi m\\u1ebb cho m\\u1ecdi d\\u1ef1 \\u00e1n.\",\"work.title\":\"C\\u00f4ng vi\\u1ec7c & D\\u1ef1 \\u00e1n\",\"work.1.category\":\"D\\u1ef0 \\u00c1N 01\",\"work.1.title\":\"OriginD\",\"work.1.description\":\"H\\u1ed7 tr\\u1ee3 t\\u1ea1o landing pgae trong 5p\",\"work.2.category\":null,\"work.2.title\":null,\"work.2.description\":null,\"contact.title\":\"K\\u1ebft n\\u1ed1i v\\u1edbi t\\u00f4i\",\"contact.subtitle\":\"Ch\\u1ecdn n\\u1ec1n t\\u1ea3ng b\\u1ea1n mu\\u1ed1n li\\u00ean l\\u1ea1c\",\"contact.zalo.link\":\"https:\\/\\/chat.zalo.me\\/\",\"contact.zalo.label\":\"Zalo\",\"contact.facebook.link\":\"https:\\/\\/www.facebook.com\\/NguyenHaiDang2005.FB\",\"contact.facebook.label\":\"Facebook\",\"contact.tiktok.link\":\"https:\\/\\/tiktok.com\\/\",\"contact.tiktok.label\":\"TikTok\",\"contact.email\":\"haidang120225@gmail.com\",\"footer.copyright\":\"OriginD - 2026\"}', NULL, 'published', '2026-08-16 05:19:29', '2026-07-15 05:02:28', '2026-07-17 05:19:29');
INSERT INTO `landing_pages` (`id`, `user_id`, `template_id`, `title`, `slug`, `data`, `domain`, `status`, `expires_at`, `created_at`, `updated_at`) VALUES ('16', '1', '11', 'Giới thiệu doanh nghiệp', 'gioi-thieu-doanh-nghiep-6a587a8e7e54b', '{\"site.title\":\"OriginD - T\\u1ea1o Website Ch\\u1ec9 Trong 5 Ph\\u00fat\",\"header.logo_text\":\"DAG\",\"menu.about\":null,\"menu.features\":null,\"menu.contact\":null,\"hero.title\":\"DAG\",\"hero.subtitle\":\"DAG- N\\u1ec1n t\\u1ea3ng t\\u1ea1o website nhanh ch\\u00f3ng, \\u0111\\u1eb9p m\\u1eaft v\\u00e0 ho\\u00e0n to\\u00e0n mi\\u1ec5n ph\\u00ed\",\"hero.cta_button\":\"https:\\/\\/www.facebook.com\\/NguyenHaiDang2005.FB\",\"hero.note\":\"DAG\",\"about.title\":\"DAG l\\u00e0 g\\u00ec?\",\"about.description\":\"DAG l\\u00e0 n\\u1ec1n t\\u1ea3ng gi\\u00fap b\\u1ea1n t\\u1ea1o website chuy\\u00ean nghi\\u1ec7p ch\\u1ec9 trong 5 ph\\u00fat m\\u00e0 kh\\u00f4ng c\\u1ea7nA bi\\u1ebft l\\u1eadp tr\\u00ecnh. \\n            V\\u1edbi h\\u00e0ng tr\\u0103m m\\u1eabu \\u0111\\u1eb9p hi\\u1ec7n \\u0111\\u1ea1i, b\\u1ea1n ch\\u1ec9 c\\u1ea7n ch\\u1ecdn v\\u00e0 ch\\u1ec9nh s\\u1eeda theo \\u00fd mu\\u1ed1n.\",\"about.benefit1\":\"Ho\\u00e0n to\\u00e0n mi\\u1ec5n ph\\u00ed DAG\",\"about.benefit2\":\"Responsive tr\\u00ean m\\u1ecdi thi\\u1ebft b\\u1ecb DAG\",\"about.benefit3\":\"T\\u00f9y ch\\u1ec9nh d\\u1ec5 d\\u00e0ng DAG\",\"about.image\":\"https:\\/\\/i.imgur.com\\/IZ7lAzD.png\",\"features.title\":\"T\\u1ea1i sao n\\u00ean ch\\u1ecdn DAG\",\"features.1.title\":\"Si\\u00eau nhanh DAG\",\"features.1.desc\":\"Ch\\u1ec9 m\\u1ea5t 5 ph\\u00fat \\u0111\\u1ec3 c\\u00f3 m\\u1ed9t website ho\\u00e0n ch\\u1ec9nh DAG\",\"features.2.title\":\"Thi\\u1ebft k\\u1ebf \\u0111\\u1eb9p DAG\",\"features.2.desc\":\"H\\u00e0ng tr\\u0103m m\\u1eabu giao di\\u1ec7n hi\\u1ec7n \\u0111\\u1ea1i, chuy\\u00ean nghi\\u1ec7p DAG\",\"features.3.title\":\"Mi\\u1ec5n ph\\u00ed 100% DAG\",\"features.3.desc\":\"S\\u1eed d\\u1ee5ng tr\\u1ecdn \\u0111\\u1eddi m\\u00e0 kh\\u00f4ng m\\u1ea5t b\\u1ea5t k\\u1ef3 chi ph\\u00ed n\\u00e0o DAG\",\"footer.logo_text\":\"OriginD DAG\",\"footer.slogan\":\"T\\u1ea1o website nhanh - \\u0110\\u1eb9p - Mi\\u1ec5n ph\\u00ed DAG\",\"footer.email\":\"contact.origind@gmail.com DAG\",\"footer.phone\":\"0866 984 097 DAG\"}', NULL, 'published', '2026-08-16 05:19:29', '2026-07-16 06:30:38', '2026-07-17 05:19:29');
INSERT INTO `landing_pages` (`id`, `user_id`, `template_id`, `title`, `slug`, `data`, `domain`, `status`, `expires_at`, `created_at`, `updated_at`) VALUES ('17', '1', '13', 'Đếm ngày yêu', 'dag', '{\"hero.page_title\":\"\\u0110\\u1ebfm Ng\\u00e0y Ch\\u00fang Ta \\u0110\\u00e3 B\\u00ean Nhau\",\"hero.title\":\"Ch\\u00fang Ta \\u0110\\u00e3 B\\u00ean Nhau DAG\",\"hero.subtitle\":\"M\\u1ed7i ng\\u00e0y b\\u00ean nhau \\u0111\\u1ec1u l\\u00e0 m\\u00f3n qu\\u00e0 \\u0111\\u1eb9p nh\\u1ea5t. DAG\",\"couple.groom_image\":\"https:\\/\\/i.pinimg.com\\/1200x\\/04\\/4a\\/78\\/044a78f85cfd05892a4381f0d7d0a477.jpg\",\"couple.groom_name\":\"DAG\",\"couple.bride_image\":\"https:\\/\\/i.pinimg.com\\/236x\\/d7\\/18\\/bb\\/d718bba37a543596f271fa1dafdd3001.jpg\",\"couple.bride_name\":\"DAG\",\"quote.content\":\"\\\"T\\u00ecnh y\\u00eau kh\\u00f4ng ph\\u1ea3i l\\u00e0 t\\u00ecm ki\\u1ebfm m\\u1ed9t ai \\u0111\\u00f3 ho\\u00e0n h\\u1ea3o, m\\u00e0 l\\u00e0 h\\u1ecdc c\\u00e1ch nh\\u00ecn th\\u1ea5y nh\\u1eefng \\u0111i\\u1ec1u tuy\\u1ec7t v\\u1eddi t\\u1eeb m\\u1ed9t ng\\u01b0\\u1eddi kh\\u00f4ng ho\\u00e0n h\\u1ea3o.\\\" DAG\",\"timeline.title\":\"H\\u00e0nh Tr\\u00ecnh T\\u00ecnh Y\\u00eau DAG\",\"timeline.items.0.date\":\"14.02.2025\",\"timeline.items.0.title\":\"\\u2764\\ufe0f L\\u1ea7n \\u0111\\u1ea7u g\\u1eb7p nhau DAG\",\"timeline.items.0.desc\":\"Gi\\u1eefa d\\u00f2ng \\u0111\\u1eddi t\\u1ea5p n\\u1eadp, \\u00e1nh m\\u1eaft ta \\u0111\\u00e3 v\\u00f4 t\\u00ecnh ch\\u1ea1m nhau t\\u1ea1i m\\u1ed9t qu\\u00e1n c\\u00e0 ph\\u00ea nh\\u1ecf th\\u01a1m m\\u00f9i \\u1ea5m c\\u00fang.DAG\",\"timeline.items.1.date\":\"08.03.2025\",\"timeline.items.1.title\":\"\\ud83c\\udf38 Bu\\u1ed5i h\\u1eb9n \\u0111\\u1ea7u ti\\u00eanDAG\",\"timeline.items.1.desc\":\"M\\u1ed9t t\\u1ed1i m\\u01b0a l\\u1ea5t ph\\u1ea5t l\\u00e3ng m\\u1ea1n, ch\\u00fang ta \\u0111\\u00e3 tr\\u00f2 chuy\\u1ec7n h\\u00e0ng gi\\u1edd v\\u1ec1 \\u01b0\\u1edbc m\\u01a1, s\\u1edf th\\u00edch v\\u00e0 nh\\u1eadn ra t\\u00e2m h\\u1ed3n \\u0111\\u1ed3ng \\u0111i\\u1ec7u.DAG\",\"timeline.items.2.date\":\"01.05.2024\",\"timeline.items.2.title\":\"\\ud83d\\udc95 Ch\\u00ednh th\\u1ee9c y\\u00eauDAG\",\"timeline.items.2.desc\":\"L\\u1eddi t\\u1ecf t\\u00ecnh ng\\u01b0\\u1ee3ng ng\\u00f9ng c\\u00f9ng b\\u00f3 h\\u1ed3ng th\\u1eafm. Ng\\u00e0y em kh\\u1ebd g\\u1eadt \\u0111\\u1ea7u \\u0111\\u1ed3ng \\u00fd tr\\u1edf th\\u00e0nh m\\u1ea3nh gh\\u00e9p ho\\u00e0n h\\u1ea3o.DAG\",\"timeline.items.3.date\":\"15.08.2025\",\"timeline.items.3.title\":\"\\u2708\\ufe0f Chuy\\u1ebfn \\u0111i \\u0111\\u1ea7u ti\\u00eanDAG\",\"timeline.items.3.desc\":\"H\\u00e0nh tr\\u00ecnh kh\\u00e1m ph\\u00e1 th\\u00e0nh ph\\u1ed1 bi\\u1ec3n r\\u1ef1c r\\u1ee1 n\\u1eafng v\\u00e0ng. C\\u00f9ng ng\\u1eafm b\\u00ecnh minh v\\u00e0 h\\u1ee9a s\\u1ebd \\u0111i kh\\u1eafp th\\u1ebf gian.DAG\",\"timeline.items.4.date\":\"10.10.2025\",\"timeline.items.4.title\":\"\\ud83c\\udf82 Sinh nh\\u1eadt c\\u00f9ng nhauDAG\",\"timeline.items.4.desc\":\"B\\u1eefa ti\\u1ec7c sinh nh\\u1eadt \\u1ea5m \\u00e1p ch\\u1ec9 c\\u00f3 hai ng\\u01b0\\u1eddi. C\\u00f9ng nguy\\u1ec7n c\\u1ea7u d\\u01b0\\u1edbi \\u00e1nh n\\u1ebfn lung linh.DAG\",\"timeline.items.5.date\":\"T\\u01b0\\u01a1ng laiDAG\",\"timeline.items.5.title\":\"\\ud83d\\udc8d M\\u00e3i m\\u00e3i v\\u1ec1 sauDAG\",\"timeline.items.5.desc\":\"Nh\\u1eefng trang s\\u00e1ch cu\\u1ed9c \\u0111\\u1eddi v\\u1eabn \\u0111ang ti\\u1ebfp t\\u1ee5c \\u0111\\u01b0\\u1ee3c vi\\u1ebft n\\u00ean b\\u1edfi t\\u00ecnh c\\u1ea3m n\\u1ed3ng n\\u00e0n c\\u1ee7a hai ta.DAG\",\"gallery.title\":\"Kho\\u1ea3nh Kh\\u1eafc K\\u1ef7 Ni\\u1ec7mDAG\",\"gallery.images.0\":\"https:\\/\\/i.pinimg.com\\/1200x\\/04\\/4a\\/78\\/044a78f85cfd05892a4381f0d7d0a477.jpg\",\"gallery.images.1\":\"https:\\/\\/i.pinimg.com\\/1200x\\/04\\/4a\\/78\\/044a78f85cfd05892a4381f0d7d0a477.jpg\",\"gallery.images.2\":\"https:\\/\\/i.pinimg.com\\/236x\\/d7\\/18\\/bb\\/d718bba37a543596f271fa1dafdd3001.jpg\",\"letter.title\":\"Th\\u01b0 G\\u1eedi Ng\\u01b0\\u1eddi Th\\u01b0\\u01a1ngDAG\",\"letter.greeting\":\"Th\\u01b0\\u01a1ng g\\u1eedi Em y\\u00eau,DAG\",\"letter.content\":\"Nhi\\u1ec1u l\\u00fac ng\\u1ed3i suy ng\\u1eabm, anh t\\u1ef1 h\\u1ecfi m\\u00ecnh \\u0111\\u00e3 l\\u00e0m g\\u00ec t\\u1ed1t \\u0111\\u1eb9p trong cu\\u1ed9c \\u0111\\u1eddi \\u0111\\u1ec3 x\\u1ee9ng \\u0111\\u00e1ng c\\u00f3 \\u0111\\u01b0\\u1ee3c em b\\u00ean c\\u1ea1nh. Em mang \\u0111\\u1ebfn cho anh th\\u1ee9 \\u00e1nh s\\u00e1ng nh\\u1eb9 nh\\u00e0ng nh\\u01b0ng ng\\u1eadp tr\\u00e0n h\\u01a1i \\u1ea5m, xoa d\\u1ecbu m\\u1ecdi gi\\u00f4ng b\\u00e3o sau nh\\u1eefng ng\\u00e0y d\\u00e0i m\\u1ecfi m\\u1ec7t.\\n                T\\u1eebng c\\u00e1i \\u00f4m si\\u1ebft ch\\u1eb7t, t\\u1eebng n\\u1ee5 c\\u01b0\\u1eddi l\\u1ea5p l\\u00e1nh c\\u1ee7a em \\u0111\\u00e3 tr\\u1edf th\\u00e0nh m\\u1ed9t ph\\u1ea7n thi\\u1ebft y\\u1ebfu trong h\\u01a1i th\\u1edf anh h\\u1eb1ng ng\\u00e0y. C\\u1ea3m \\u01a1n em v\\u00ec \\u0111\\u00e3 d\\u1ecbu d\\u00e0ng, \\u0111\\u00e3 l\\u1eafng nghe, \\u0111\\u00e3 c\\u00f9ng anh \\u0111i qua nh\\u1eefng cung b\\u1eadc x\\u00fac c\\u1ea3m tuy\\u1ec7t di\\u1ec7u nh\\u1ea5t.\\n                Y\\u00eau em kh\\u00f4ng ch\\u1ec9 l\\u00e0 l\\u1eddi n\\u00f3i \\u0111\\u1ea7u m\\u00f4i, \\u0111\\u00f3 l\\u00e0 h\\u00e0nh tr\\u00ecnh n\\u1ed7 l\\u1ef1c \\u0111\\u1ec3 tr\\u1edf th\\u00e0nh m\\u1ed9t \\u0111i\\u1ec3m t\\u1ef1a v\\u1eefng v\\u00e0ng nh\\u1ea5t, mang l\\u1ea1i h\\u1ea1nh ph\\u00fac th\\u1ef1c s\\u1ef1 cho em m\\u00e3i m\\u00e3i v\\u1ec1 sau.DAG\",\"letter.closing\":\"Y\\u00eau em v\\u00f4 \\u0111i\\u1ec1u ki\\u1ec7nDAG\",\"letter.signature\":\"Anh c\\u1ee7a EmDAG\",\"anniversary.start_date\":\"2026-07-16\"}', NULL, 'published', '2026-08-16 05:19:29', '2026-07-16 11:13:58', '2026-07-17 05:19:29');
INSERT INTO `landing_pages` (`id`, `user_id`, `template_id`, `title`, `slug`, `data`, `domain`, `status`, `expires_at`, `created_at`, `updated_at`) VALUES ('18', '5', '10', 'Giới thiệu bản thân', 'gioi-thieu-ban-than-6a5905664c7ae', '{\"site.title\":\"H\\u1ecd T\\u00ean\",\"header.name\":\"H\\u1ecd T\\u00ean\",\"menu.about\":\"#about\",\"menu.work\":\"#work\",\"menu.contact\":\"#contact\",\"hero.badge\":\"OPEN FOR OPPORTUNITIES\",\"hero.name\":\"H\\u1ecd T\\u00ean\",\"hero.subtitle\":\"M\\u1ed9t ng\\u01b0\\u1eddi \\u0111a ng\\u00e0nh \\u2022 \\u0110am m\\u00ea s\\u00e1ng t\\u1ea1o \\u2022 Lu\\u00f4n h\\u1ecdc h\\u1ecfi\",\"hero.profile_image\":\"https:\\/\\/phukiennillkin.com\\/wp-content\\/uploads\\/2026\\/03\\/anh-girl-xinh-14.jpg\",\"about.title\":\"V\\u1ec1 t\\u00f4i\",\"about.description\":\"T\\u00f4i l\\u00e0 m\\u1ed9t ng\\u01b0\\u1eddi h\\u1ecdc h\\u1ecfi kh\\u00f4ng ng\\u1eebng v\\u00e0 \\u0111am m\\u00ea bi\\u1ebfn \\u00fd t\\u01b0\\u1edfng th\\u00e0nh hi\\u1ec7n th\\u1ef1c. \\r\\n                        V\\u1edbi n\\u1ec1n t\\u1ea3ng \\u0111a ng\\u00e0nh, t\\u00f4i c\\u00f3 kh\\u1ea3 n\\u0103ng th\\u00edch \\u1ee9ng nhanh v\\u00e0 mang l\\u1ea1i g\\u00f3c nh\\u00ecn m\\u1edbi m\\u1ebb cho m\\u1ecdi d\\u1ef1 \\u00e1n.\",\"work.title\":\"C\\u00f4ng vi\\u1ec7c & D\\u1ef1 \\u00e1n\",\"work.1.category\":\"D\\u1ef0 \\u00c1N 01\",\"work.1.title\":\"T\\u00ean d\\u1ef1 \\u00e1n m\\u1ed9t\",\"work.1.description\":\"M\\u00f4 t\\u1ea3 ng\\u1eafn v\\u1ec1 d\\u1ef1 \\u00e1n n\\u00e0y.\",\"work.2.category\":\"D\\u1ef0 \\u00c1N 02\",\"work.2.title\":\"T\\u00ean d\\u1ef1 \\u00e1n hai\",\"work.2.description\":\"M\\u00f4 t\\u1ea3 ng\\u1eafn v\\u1ec1 d\\u1ef1 \\u00e1n n\\u00e0y.\",\"contact.title\":\"K\\u1ebft n\\u1ed1i v\\u1edbi t\\u00f4i\",\"contact.subtitle\":\"Ch\\u1ecdn n\\u1ec1n t\\u1ea3ng b\\u1ea1n mu\\u1ed1n li\\u00ean l\\u1ea1c\",\"contact.zalo.link\":\"https:\\/\\/zalo.me\\/\",\"contact.zalo.label\":\"Zalo\",\"contact.facebook.link\":\"https:\\/\\/facebook.com\\/\",\"contact.facebook.label\":\"Facebook\",\"contact.tiktok.link\":\"https:\\/\\/tiktok.com\\/\",\"contact.tiktok.label\":\"TikTok\",\"contact.email\":\"mailto:tenban@email.com\",\"footer.copyright\":\"OriginD - 2026\"}', NULL, 'published', '2026-11-13 16:47:56', '2026-07-16 16:23:00', '2026-07-17 05:43:48');
INSERT INTO `landing_pages` (`id`, `user_id`, `template_id`, `title`, `slug`, `data`, `domain`, `status`, `expires_at`, `created_at`, `updated_at`) VALUES ('20', '1', '13', 'Đếm ngày yêu', 'dem-ngay-yeu-6a59bc48bdade', '{\"hero.page_title\":\"\\u0110\\u1ebfm Ng\\u00e0y Ch\\u00fang Ta \\u0110\\u00e3 B\\u00ean Nhau\",\"hero.title\":\"Ch\\u00fang Ta \\u0110\\u00e3 B\\u00ean Nhau\",\"hero.subtitle\":\"M\\u1ed7i ng\\u00e0y b\\u00ean nhau \\u0111\\u1ec1u l\\u00e0 m\\u00f3n qu\\u00e0 \\u0111\\u1eb9p nh\\u1ea5t.\",\"couple.groom_image\":\"https:\\/\\/i.pinimg.com\\/236x\\/d7\\/18\\/bb\\/d718bba37a543596f271fa1dafdd3001.jpg\",\"couple.groom_name\":\"Groom \\ud83d\\udc51\",\"couple.bride_image\":\"https:\\/\\/i.pinimg.com\\/1200x\\/04\\/4a\\/78\\/044a78f85cfd05892a4381f0d7d0a477.jpg\",\"couple.bride_name\":\"Bride \\ud83c\\udf38\",\"quote.content\":\"\\\"T\\u00ecnh y\\u00eau kh\\u00f4ng ph\\u1ea3i l\\u00e0 t\\u00ecm ki\\u1ebfm m\\u1ed9t ai \\u0111\\u00f3 ho\\u00e0n h\\u1ea3o, m\\u00e0 l\\u00e0 h\\u1ecdc c\\u00e1ch nh\\u00ecn th\\u1ea5y nh\\u1eefng \\u0111i\\u1ec1u tuy\\u1ec7t v\\u1eddi t\\u1eeb m\\u1ed9t ng\\u01b0\\u1eddi kh\\u00f4ng ho\\u00e0n h\\u1ea3o.\\\"\",\"timeline.title\":\"H\\u00e0nh Tr\\u00ecnh T\\u00ecnh Y\\u00eau\",\"timeline.items.0.date\":\"14.02.2024\",\"timeline.items.0.title\":\"\\u2764\\ufe0f L\\u1ea7n \\u0111\\u1ea7u g\\u1eb7p nhau\",\"timeline.items.0.desc\":\"Gi\\u1eefa d\\u00f2ng \\u0111\\u1eddi t\\u1ea5p n\\u1eadp, \\u00e1nh m\\u1eaft ta \\u0111\\u00e3 v\\u00f4 t\\u00ecnh ch\\u1ea1m nhau t\\u1ea1i m\\u1ed9t qu\\u00e1n c\\u00e0 ph\\u00ea nh\\u1ecf th\\u01a1m m\\u00f9i \\u1ea5m c\\u00fang.\",\"timeline.items.1.date\":\"08.03.2024\",\"timeline.items.1.title\":\"\\ud83c\\udf38 Bu\\u1ed5i h\\u1eb9n \\u0111\\u1ea7u ti\\u00ean\",\"timeline.items.1.desc\":\"M\\u1ed9t t\\u1ed1i m\\u01b0a l\\u1ea5t ph\\u1ea5t l\\u00e3ng m\\u1ea1n, ch\\u00fang ta \\u0111\\u00e3 tr\\u00f2 chuy\\u1ec7n h\\u00e0ng gi\\u1edd v\\u1ec1 \\u01b0\\u1edbc m\\u01a1, s\\u1edf th\\u00edch v\\u00e0 nh\\u1eadn ra t\\u00e2m h\\u1ed3n \\u0111\\u1ed3ng \\u0111i\\u1ec7u.\",\"timeline.items.2.date\":\"01.05.2024\",\"timeline.items.2.title\":\"\\ud83d\\udc95 Ch\\u00ednh th\\u1ee9c y\\u00eau\",\"timeline.items.2.desc\":\"L\\u1eddi t\\u1ecf t\\u00ecnh ng\\u01b0\\u1ee3ng ng\\u00f9ng c\\u00f9ng b\\u00f3 h\\u1ed3ng th\\u1eafm. Ng\\u00e0y em kh\\u1ebd g\\u1eadt \\u0111\\u1ea7u \\u0111\\u1ed3ng \\u00fd tr\\u1edf th\\u00e0nh m\\u1ea3nh gh\\u00e9p ho\\u00e0n h\\u1ea3o.\",\"timeline.items.3.date\":\"15.08.2024\",\"timeline.items.3.title\":\"\\u2708\\ufe0f Chuy\\u1ebfn \\u0111i \\u0111\\u1ea7u ti\\u00ean\",\"timeline.items.3.desc\":\"H\\u00e0nh tr\\u00ecnh kh\\u00e1m ph\\u00e1 th\\u00e0nh ph\\u1ed1 bi\\u1ec3n r\\u1ef1c r\\u1ee1 n\\u1eafng v\\u00e0ng. C\\u00f9ng ng\\u1eafm b\\u00ecnh minh v\\u00e0 h\\u1ee9a s\\u1ebd \\u0111i kh\\u1eafp th\\u1ebf gian.\",\"timeline.items.4.date\":\"10.10.2024\",\"timeline.items.4.title\":\"\\ud83c\\udf82 Sinh nh\\u1eadt c\\u00f9ng nhau\",\"timeline.items.4.desc\":\"B\\u1eefa ti\\u1ec7c sinh nh\\u1eadt \\u1ea5m \\u00e1p ch\\u1ec9 c\\u00f3 hai ng\\u01b0\\u1eddi. C\\u00f9ng nguy\\u1ec7n c\\u1ea7u d\\u01b0\\u1edbi \\u00e1nh n\\u1ebfn lung linh.\",\"timeline.items.5.date\":\"T\\u01b0\\u01a1ng lai\",\"timeline.items.5.title\":\"\\ud83d\\udc8d M\\u00e3i m\\u00e3i v\\u1ec1 sau\",\"timeline.items.5.desc\":\"Nh\\u1eefng trang s\\u00e1ch cu\\u1ed9c \\u0111\\u1eddi v\\u1eabn \\u0111ang ti\\u1ebfp t\\u1ee5c \\u0111\\u01b0\\u1ee3c vi\\u1ebft n\\u00ean b\\u1edfi t\\u00ecnh c\\u1ea3m n\\u1ed3ng n\\u00e0n c\\u1ee7a hai ta.\",\"gallery.title\":\"Kho\\u1ea3nh Kh\\u1eafc K\\u1ef7 Ni\\u1ec7m\",\"gallery.images.0\":\"https:\\/\\/images.unsplash.com\\/photo-1518199266791-5375a83190b7?auto=format&fit=crop&q=80&w=600\",\"gallery.images.1\":\"https:\\/\\/images.unsplash.com\\/photo-1515934751635-c81c6bc9a2d8?auto=format&fit=crop&q=80&w=600\",\"gallery.images.2\":\"https:\\/\\/images.unsplash.com\\/photo-1510154221590-ff63e90a136f?auto=format&fit=crop&q=80&w=600\",\"letter.title\":\"Th\\u01b0 G\\u1eedi Ng\\u01b0\\u1eddi Th\\u01b0\\u01a1ng\",\"letter.greeting\":\"Th\\u01b0\\u01a1ng g\\u1eedi Em y\\u00eau,\",\"letter.content\":\"Nhi\\u1ec1u l\\u00fac ng\\u1ed3i suy ng\\u1eabm, anh t\\u1ef1 h\\u1ecfi m\\u00ecnh \\u0111\\u00e3 l\\u00e0m g\\u00ec t\\u1ed1t \\u0111\\u1eb9p trong cu\\u1ed9c \\u0111\\u1eddi \\u0111\\u1ec3 x\\u1ee9ng \\u0111\\u00e1ng c\\u00f3 \\u0111\\u01b0\\u1ee3c em b\\u00ean c\\u1ea1nh. Em mang \\u0111\\u1ebfn cho anh th\\u1ee9 \\u00e1nh s\\u00e1ng nh\\u1eb9 nh\\u00e0ng nh\\u01b0ng ng\\u1eadp tr\\u00e0n h\\u01a1i \\u1ea5m, xoa d\\u1ecbu m\\u1ecdi gi\\u00f4ng b\\u00e3o sau nh\\u1eefng ng\\u00e0y d\\u00e0i m\\u1ecfi m\\u1ec7t.\\r\\n                T\\u1eebng c\\u00e1i \\u00f4m si\\u1ebft ch\\u1eb7t, t\\u1eebng n\\u1ee5 c\\u01b0\\u1eddi l\\u1ea5p l\\u00e1nh c\\u1ee7a em \\u0111\\u00e3 tr\\u1edf th\\u00e0nh m\\u1ed9t ph\\u1ea7n thi\\u1ebft y\\u1ebfu trong h\\u01a1i th\\u1edf anh h\\u1eb1ng ng\\u00e0y. C\\u1ea3m \\u01a1n em v\\u00ec \\u0111\\u00e3 d\\u1ecbu d\\u00e0ng, \\u0111\\u00e3 l\\u1eafng nghe, \\u0111\\u00e3 c\\u00f9ng anh \\u0111i qua nh\\u1eefng cung b\\u1eadc x\\u00fac c\\u1ea3m tuy\\u1ec7t di\\u1ec7u nh\\u1ea5t.\\r\\n                Y\\u00eau em kh\\u00f4ng ch\\u1ec9 l\\u00e0 l\\u1eddi n\\u00f3i \\u0111\\u1ea7u m\\u00f4i, \\u0111\\u00f3 l\\u00e0 h\\u00e0nh tr\\u00ecnh n\\u1ed7 l\\u1ef1c \\u0111\\u1ec3 tr\\u1edf th\\u00e0nh m\\u1ed9t \\u0111i\\u1ec3m t\\u1ef1a v\\u1eefng v\\u00e0ng nh\\u1ea5t, mang l\\u1ea1i h\\u1ea1nh ph\\u00fac th\\u1ef1c s\\u1ef1 cho em m\\u00e3i m\\u00e3i v\\u1ec1 sau.\",\"letter.closing\":\"Y\\u00eau em v\\u00f4 \\u0111i\\u1ec1u ki\\u1ec7n\",\"letter.signature\":\"Anh c\\u1ee7a Em\",\"anniversary.start_date\":\"2024-05-01\"}', NULL, 'published', '2026-08-16 05:19:29', '2026-07-17 05:23:20', '2026-07-17 05:36:21');
INSERT INTO `landing_pages` (`id`, `user_id`, `template_id`, `title`, `slug`, `data`, `domain`, `status`, `expires_at`, `created_at`, `updated_at`) VALUES ('21', '1', '13', 'Đếm ngày yêu', 'dem-ngay-yeu-6a59bd2bcfa05', '{\"hero.page_title\":\"\\u0110\\u1ebfm Ng\\u00e0y Ch\\u00fang Ta \\u0110\\u00e3 B\\u00ean Nhau\",\"hero.title\":\"Ch\\u00fang Ta \\u0110\\u00e3 B\\u00ean Nhau\",\"hero.subtitle\":\"M\\u1ed7i ng\\u00e0y b\\u00ean nhau \\u0111\\u1ec1u l\\u00e0 m\\u00f3n qu\\u00e0 \\u0111\\u1eb9p nh\\u1ea5t.\",\"couple.groom_image\":\"https:\\/\\/i.pinimg.com\\/236x\\/d7\\/18\\/bb\\/d718bba37a543596f271fa1dafdd3001.jpg\",\"couple.groom_name\":\"Groom \\ud83d\\udc51\",\"couple.bride_image\":\"https:\\/\\/i.pinimg.com\\/1200x\\/04\\/4a\\/78\\/044a78f85cfd05892a4381f0d7d0a477.jpg\",\"couple.bride_name\":\"Bride \\ud83c\\udf38\",\"quote.content\":\"\\\"T\\u00ecnh y\\u00eau kh\\u00f4ng ph\\u1ea3i l\\u00e0 t\\u00ecm ki\\u1ebfm m\\u1ed9t ai \\u0111\\u00f3 ho\\u00e0n h\\u1ea3o, m\\u00e0 l\\u00e0 h\\u1ecdc c\\u00e1ch nh\\u00ecn th\\u1ea5y nh\\u1eefng \\u0111i\\u1ec1u tuy\\u1ec7t v\\u1eddi t\\u1eeb m\\u1ed9t ng\\u01b0\\u1eddi kh\\u00f4ng ho\\u00e0n h\\u1ea3o.\\\"\",\"timeline.title\":\"H\\u00e0nh Tr\\u00ecnh T\\u00ecnh Y\\u00eau\",\"timeline.items.0.date\":\"14.02.2024\",\"timeline.items.0.title\":\"\\u2764\\ufe0f L\\u1ea7n \\u0111\\u1ea7u g\\u1eb7p nhau\",\"timeline.items.0.desc\":\"Gi\\u1eefa d\\u00f2ng \\u0111\\u1eddi t\\u1ea5p n\\u1eadp, \\u00e1nh m\\u1eaft ta \\u0111\\u00e3 v\\u00f4 t\\u00ecnh ch\\u1ea1m nhau t\\u1ea1i m\\u1ed9t qu\\u00e1n c\\u00e0 ph\\u00ea nh\\u1ecf th\\u01a1m m\\u00f9i \\u1ea5m c\\u00fang.\",\"timeline.items.1.date\":\"08.03.2024\",\"timeline.items.1.title\":\"\\ud83c\\udf38 Bu\\u1ed5i h\\u1eb9n \\u0111\\u1ea7u ti\\u00ean\",\"timeline.items.1.desc\":\"M\\u1ed9t t\\u1ed1i m\\u01b0a l\\u1ea5t ph\\u1ea5t l\\u00e3ng m\\u1ea1n, ch\\u00fang ta \\u0111\\u00e3 tr\\u00f2 chuy\\u1ec7n h\\u00e0ng gi\\u1edd v\\u1ec1 \\u01b0\\u1edbc m\\u01a1, s\\u1edf th\\u00edch v\\u00e0 nh\\u1eadn ra t\\u00e2m h\\u1ed3n \\u0111\\u1ed3ng \\u0111i\\u1ec7u.\",\"timeline.items.2.date\":\"01.05.2024\",\"timeline.items.2.title\":\"\\ud83d\\udc95 Ch\\u00ednh th\\u1ee9c y\\u00eau\",\"timeline.items.2.desc\":\"L\\u1eddi t\\u1ecf t\\u00ecnh ng\\u01b0\\u1ee3ng ng\\u00f9ng c\\u00f9ng b\\u00f3 h\\u1ed3ng th\\u1eafm. Ng\\u00e0y em kh\\u1ebd g\\u1eadt \\u0111\\u1ea7u \\u0111\\u1ed3ng \\u00fd tr\\u1edf th\\u00e0nh m\\u1ea3nh gh\\u00e9p ho\\u00e0n h\\u1ea3o.\",\"timeline.items.3.date\":\"15.08.2024\",\"timeline.items.3.title\":\"\\u2708\\ufe0f Chuy\\u1ebfn \\u0111i \\u0111\\u1ea7u ti\\u00ean\",\"timeline.items.3.desc\":\"H\\u00e0nh tr\\u00ecnh kh\\u00e1m ph\\u00e1 th\\u00e0nh ph\\u1ed1 bi\\u1ec3n r\\u1ef1c r\\u1ee1 n\\u1eafng v\\u00e0ng. C\\u00f9ng ng\\u1eafm b\\u00ecnh minh v\\u00e0 h\\u1ee9a s\\u1ebd \\u0111i kh\\u1eafp th\\u1ebf gian.\",\"timeline.items.4.date\":\"10.10.2024\",\"timeline.items.4.title\":\"\\ud83c\\udf82 Sinh nh\\u1eadt c\\u00f9ng nhau\",\"timeline.items.4.desc\":\"B\\u1eefa ti\\u1ec7c sinh nh\\u1eadt \\u1ea5m \\u00e1p ch\\u1ec9 c\\u00f3 hai ng\\u01b0\\u1eddi. C\\u00f9ng nguy\\u1ec7n c\\u1ea7u d\\u01b0\\u1edbi \\u00e1nh n\\u1ebfn lung linh.\",\"timeline.items.5.date\":\"T\\u01b0\\u01a1ng lai\",\"timeline.items.5.title\":\"\\ud83d\\udc8d M\\u00e3i m\\u00e3i v\\u1ec1 sau\",\"timeline.items.5.desc\":\"Nh\\u1eefng trang s\\u00e1ch cu\\u1ed9c \\u0111\\u1eddi v\\u1eabn \\u0111ang ti\\u1ebfp t\\u1ee5c \\u0111\\u01b0\\u1ee3c vi\\u1ebft n\\u00ean b\\u1edfi t\\u00ecnh c\\u1ea3m n\\u1ed3ng n\\u00e0n c\\u1ee7a hai ta.\",\"gallery.title\":\"Kho\\u1ea3nh Kh\\u1eafc K\\u1ef7 Ni\\u1ec7m\",\"gallery.images.0\":\"https:\\/\\/images.unsplash.com\\/photo-1518199266791-5375a83190b7?auto=format&fit=crop&q=80&w=600\",\"gallery.images.1\":\"https:\\/\\/images.unsplash.com\\/photo-1515934751635-c81c6bc9a2d8?auto=format&fit=crop&q=80&w=600\",\"gallery.images.2\":\"https:\\/\\/images.unsplash.com\\/photo-1510154221590-ff63e90a136f?auto=format&fit=crop&q=80&w=600\",\"letter.title\":\"Th\\u01b0 G\\u1eedi Ng\\u01b0\\u1eddi Th\\u01b0\\u01a1ng\",\"letter.greeting\":\"Th\\u01b0\\u01a1ng g\\u1eedi Em y\\u00eau,\",\"letter.content\":\"Nhi\\u1ec1u l\\u00fac ng\\u1ed3i suy ng\\u1eabm, anh t\\u1ef1 h\\u1ecfi m\\u00ecnh \\u0111\\u00e3 l\\u00e0m g\\u00ec t\\u1ed1t \\u0111\\u1eb9p trong cu\\u1ed9c \\u0111\\u1eddi \\u0111\\u1ec3 x\\u1ee9ng \\u0111\\u00e1ng c\\u00f3 \\u0111\\u01b0\\u1ee3c em b\\u00ean c\\u1ea1nh. Em mang \\u0111\\u1ebfn cho anh th\\u1ee9 \\u00e1nh s\\u00e1ng nh\\u1eb9 nh\\u00e0ng nh\\u01b0ng ng\\u1eadp tr\\u00e0n h\\u01a1i \\u1ea5m, xoa d\\u1ecbu m\\u1ecdi gi\\u00f4ng b\\u00e3o sau nh\\u1eefng ng\\u00e0y d\\u00e0i m\\u1ecfi m\\u1ec7t.\\r\\n                T\\u1eebng c\\u00e1i \\u00f4m si\\u1ebft ch\\u1eb7t, t\\u1eebng n\\u1ee5 c\\u01b0\\u1eddi l\\u1ea5p l\\u00e1nh c\\u1ee7a em \\u0111\\u00e3 tr\\u1edf th\\u00e0nh m\\u1ed9t ph\\u1ea7n thi\\u1ebft y\\u1ebfu trong h\\u01a1i th\\u1edf anh h\\u1eb1ng ng\\u00e0y. C\\u1ea3m \\u01a1n em v\\u00ec \\u0111\\u00e3 d\\u1ecbu d\\u00e0ng, \\u0111\\u00e3 l\\u1eafng nghe, \\u0111\\u00e3 c\\u00f9ng anh \\u0111i qua nh\\u1eefng cung b\\u1eadc x\\u00fac c\\u1ea3m tuy\\u1ec7t di\\u1ec7u nh\\u1ea5t.\\r\\n                Y\\u00eau em kh\\u00f4ng ch\\u1ec9 l\\u00e0 l\\u1eddi n\\u00f3i \\u0111\\u1ea7u m\\u00f4i, \\u0111\\u00f3 l\\u00e0 h\\u00e0nh tr\\u00ecnh n\\u1ed7 l\\u1ef1c \\u0111\\u1ec3 tr\\u1edf th\\u00e0nh m\\u1ed9t \\u0111i\\u1ec3m t\\u1ef1a v\\u1eefng v\\u00e0ng nh\\u1ea5t, mang l\\u1ea1i h\\u1ea1nh ph\\u00fac th\\u1ef1c s\\u1ef1 cho em m\\u00e3i m\\u00e3i v\\u1ec1 sau.\",\"letter.closing\":\"Y\\u00eau em v\\u00f4 \\u0111i\\u1ec1u ki\\u1ec7n\",\"letter.signature\":\"Anh c\\u1ee7a Em\",\"anniversary.start_date\":\"2024-05-01\"}', NULL, 'published', '2026-08-16 05:19:29', '2026-07-17 05:27:07', '2026-07-17 05:36:21');
INSERT INTO `landing_pages` (`id`, `user_id`, `template_id`, `title`, `slug`, `data`, `domain`, `status`, `expires_at`, `created_at`, `updated_at`) VALUES ('22', '5', '11', 'Giới thiệu doanh nghiệp', 'gioi-thieu-doanh-nghiep-6a59bfe133371', '{\"site.title\":\"OriginD - T\\u1ea1o Website Ch\\u1ec9 Trong 5 Ph\\u00fat\",\"header.logo_text\":\"OriginD\",\"menu.about\":\"#about\",\"menu.features\":\"#features\",\"menu.contact\":\"#contact\",\"hero.title\":\"T\\u1ea1o website chuy\\u00ean nghi\\u1ec7pch\\u1ec9 trong 5 ph\\u00fat\",\"hero.subtitle\":\"OriginD - N\\u1ec1n t\\u1ea3ng t\\u1ea1o website nhanh ch\\u00f3ng, \\u0111\\u1eb9p m\\u1eaft v\\u00e0 ho\\u00e0n to\\u00e0n mi\\u1ec5n ph\\u00ed\",\"hero.cta_button\":\"https:\\/\\/www.facebook.com\\/NguyenHaiDang2005.FB\",\"hero.note\":\"Kh\\u00f4ng c\\u1ea7n th\\u1ebb t\\u00edn d\\u1ee5ng \\u2022 Kh\\u00f4ng c\\u1ea7n bi\\u1ebft code\",\"about.title\":\"OriginD l\\u00e0 g\\u00ec?\",\"about.description\":\"OriginD l\\u00e0 n\\u1ec1n t\\u1ea3ng gi\\u00fap b\\u1ea1n t\\u1ea1o website chuy\\u00ean nghi\\u1ec7p ch\\u1ec9 trong 5 ph\\u00fat m\\u00e0 kh\\u00f4ng c\\u1ea7n bi\\u1ebft l\\u1eadp tr\\u00ecnh. \\r\\n            V\\u1edbi h\\u00e0ng tr\\u0103m m\\u1eabu \\u0111\\u1eb9p hi\\u1ec7n \\u0111\\u1ea1i, b\\u1ea1n ch\\u1ec9 c\\u1ea7n ch\\u1ecdn v\\u00e0 ch\\u1ec9nh s\\u1eeda theo \\u00fd mu\\u1ed1n.\",\"about.benefit1\":\"Ho\\u00e0n to\\u00e0n mi\\u1ec5n ph\\u00ed\",\"about.benefit2\":\"Responsive tr\\u00ean m\\u1ecdi thi\\u1ebft b\\u1ecb\",\"about.benefit3\":\"T\\u00f9y ch\\u1ec9nh d\\u1ec5 d\\u00e0ng\",\"about.image\":\"https:\\/\\/i.imgur.com\\/IZ7lAzD.png\",\"features.title\":\"T\\u1ea1i sao n\\u00ean ch\\u1ecdn OriginD?\",\"features.1.title\":\"Si\\u00eau nhanh\",\"features.1.desc\":\"Ch\\u1ec9 m\\u1ea5t 5 ph\\u00fat \\u0111\\u1ec3 c\\u00f3 m\\u1ed9t website ho\\u00e0n ch\\u1ec9nh\",\"features.2.title\":\"Thi\\u1ebft k\\u1ebf \\u0111\\u1eb9p\",\"features.2.desc\":\"H\\u00e0ng tr\\u0103m m\\u1eabu giao di\\u1ec7n hi\\u1ec7n \\u0111\\u1ea1i, chuy\\u00ean nghi\\u1ec7p\",\"features.3.title\":\"Mi\\u1ec5n ph\\u00ed 100%\",\"features.3.desc\":\"S\\u1eed d\\u1ee5ng tr\\u1ecdn \\u0111\\u1eddi m\\u00e0 kh\\u00f4ng m\\u1ea5t b\\u1ea5t k\\u1ef3 chi ph\\u00ed n\\u00e0o\",\"footer.logo_text\":\"OriginD\",\"footer.slogan\":\"T\\u1ea1o website nhanh - \\u0110\\u1eb9p - Mi\\u1ec5n ph\\u00ed\",\"footer.email\":\"contact.origind@gmail.com\",\"footer.phone\":\"0866 984 097\"}', NULL, 'published', '2026-12-13 16:40:10', '2026-07-17 05:38:41', '2026-07-17 05:43:48');
