INSERT INTO `landing_pages` (`id`, `user_id`, `template_id`, `title`, `slug`, `data`, `domain`, `status`, `expires_at`, `created_at`, `updated_at`) VALUES ('25', '5', '13', 'Đếm ngày yêu', 'dem-ngay-yeu-6a59ca2e2ad7a', '{\"hero.page_title\":\"\\u0110\\u1ebfm Ng\\u00e0y Ch\\u00fang Ta \\u0110\\u00e3 B\\u00ean Nhau\",\"hero.title\":\"Ch\\u00fang Ta \\u0110\\u00e3 B\\u00ean Nhau\",\"hero.subtitle\":\"M\\u1ed7i ng\\u00e0y b\\u00ean nhau \\u0111\\u1ec1u l\\u00e0 m\\u00f3n qu\\u00e0 \\u0111\\u1eb9p nh\\u1ea5t.\",\"couple.groom_image\":\"https:\\/\\/i.pinimg.com\\/236x\\/d7\\/18\\/bb\\/d718bba37a543596f271fa1dafdd3001.jpg\",\"couple.groom_name\":\"Groom \\ud83d\\udc51\",\"couple.bride_image\":\"https:\\/\\/i.pinimg.com\\/1200x\\/04\\/4a\\/78\\/044a78f85cfd05892a4381f0d7d0a477.jpg\",\"couple.bride_name\":\"Bride \\ud83c\\udf38\",\"quote.content\":\"\\\"T\\u00ecnh y\\u00eau kh\\u00f4ng ph\\u1ea3i l\\u00e0 t\\u00ecm ki\\u1ebfm m\\u1ed9t ai \\u0111\\u00f3 ho\\u00e0n h\\u1ea3o, m\\u00e0 l\\u00e0 h\\u1ecdc c\\u00e1ch nh\\u00ecn th\\u1ea5y nh\\u1eefng \\u0111i\\u1ec1u tuy\\u1ec7t v\\u1eddi t\\u1eeb m\\u1ed9t ng\\u01b0\\u1eddi kh\\u00f4ng ho\\u00e0n h\\u1ea3o.\\\"\",\"timeline.title\":\"H\\u00e0nh Tr\\u00ecnh T\\u00ecnh Y\\u00eau\",\"timeline.items.0.date\":\"14.02.2024\",\"timeline.items.0.title\":\"\\u2764\\ufe0f L\\u1ea7n \\u0111\\u1ea7u g\\u1eb7p nhau\",\"timeline.items.0.desc\":\"Gi\\u1eefa d\\u00f2ng \\u0111\\u1eddi t\\u1ea5p n\\u1eadp, \\u00e1nh m\\u1eaft ta \\u0111\\u00e3 v\\u00f4 t\\u00ecnh ch\\u1ea1m nhau t\\u1ea1i m\\u1ed9t qu\\u00e1n c\\u00e0 ph\\u00ea nh\\u1ecf th\\u01a1m m\\u00f9i \\u1ea5m c\\u00fang.\",\"timeline.items.1.date\":\"08.03.2024\",\"timeline.items.1.title\":\"\\ud83c\\udf38 Bu\\u1ed5i h\\u1eb9n \\u0111\\u1ea7u ti\\u00ean\",\"timeline.items.1.desc\":\"M\\u1ed9t t\\u1ed1i m\\u01b0a l\\u1ea5t ph\\u1ea5t l\\u00e3ng m\\u1ea1n, ch\\u00fang ta \\u0111\\u00e3 tr\\u00f2 chuy\\u1ec7n h\\u00e0ng gi\\u1edd v\\u1ec1 \\u01b0\\u1edbc m\\u01a1, s\\u1edf th\\u00edch v\\u00e0 nh\\u1eadn ra t\\u00e2m h\\u1ed3n \\u0111\\u1ed3ng \\u0111i\\u1ec7u.\",\"timeline.items.2.date\":\"01.05.2024\",\"timeline.items.2.title\":\"\\ud83d\\udc95 Ch\\u00ednh th\\u1ee9c y\\u00eau\",\"timeline.items.2.desc\":\"L\\u1eddi t\\u1ecf t\\u00ecnh ng\\u01b0\\u1ee3ng ng\\u00f9ng c\\u00f9ng b\\u00f3 h\\u1ed3ng th\\u1eafm. Ng\\u00e0y em kh\\u1ebd g\\u1eadt \\u0111\\u1ea7u \\u0111\\u1ed3ng \\u00fd tr\\u1edf th\\u00e0nh m\\u1ea3nh gh\\u00e9p ho\\u00e0n h\\u1ea3o.\",\"timeline.items.3.date\":\"15.08.2024\",\"timeline.items.3.title\":\"\\u2708\\ufe0f Chuy\\u1ebfn \\u0111i \\u0111\\u1ea7u ti\\u00ean\",\"timeline.items.3.desc\":\"H\\u00e0nh tr\\u00ecnh kh\\u00e1m ph\\u00e1 th\\u00e0nh ph\\u1ed1 bi\\u1ec3n r\\u1ef1c r\\u1ee1 n\\u1eafng v\\u00e0ng. C\\u00f9ng ng\\u1eafm b\\u00ecnh minh v\\u00e0 h\\u1ee9a s\\u1ebd \\u0111i kh\\u1eafp th\\u1ebf gian.\",\"timeline.items.4.date\":\"10.10.2024\",\"timeline.items.4.title\":\"\\ud83c\\udf82 Sinh nh\\u1eadt c\\u00f9ng nhau\",\"timeline.items.4.desc\":\"B\\u1eefa ti\\u1ec7c sinh nh\\u1eadt \\u1ea5m \\u00e1p ch\\u1ec9 c\\u00f3 hai ng\\u01b0\\u1eddi. C\\u00f9ng nguy\\u1ec7n c\\u1ea7u d\\u01b0\\u1edbi \\u00e1nh n\\u1ebfn lung linh.\",\"timeline.items.5.date\":\"T\\u01b0\\u01a1ng lai\",\"timeline.items.5.title\":\"\\ud83d\\udc8d M\\u00e3i m\\u00e3i v\\u1ec1 sau\",\"timeline.items.5.desc\":\"Nh\\u1eefng trang s\\u00e1ch cu\\u1ed9c \\u0111\\u1eddi v\\u1eabn \\u0111ang ti\\u1ebfp t\\u1ee5c \\u0111\\u01b0\\u1ee3c vi\\u1ebft n\\u00ean b\\u1edfi t\\u00ecnh c\\u1ea3m n\\u1ed3ng n\\u00e0n c\\u1ee7a hai ta.\",\"gallery.title\":\"Kho\\u1ea3nh Kh\\u1eafc K\\u1ef7 Ni\\u1ec7m\",\"gallery.images.0\":\"https:\\/\\/images.unsplash.com\\/photo-1518199266791-5375a83190b7?auto=format&fit=crop&q=80&w=600\",\"gallery.images.1\":\"https:\\/\\/images.unsplash.com\\/photo-1515934751635-c81c6bc9a2d8?auto=format&fit=crop&q=80&w=600\",\"gallery.images.2\":\"https:\\/\\/images.unsplash.com\\/photo-1510154221590-ff63e90a136f?auto=format&fit=crop&q=80&w=600\",\"letter.title\":\"Th\\u01b0 G\\u1eedi Ng\\u01b0\\u1eddi Th\\u01b0\\u01a1ng\",\"letter.greeting\":\"Th\\u01b0\\u01a1ng g\\u1eedi Em y\\u00eau,\",\"letter.content\":\"Nhi\\u1ec1u l\\u00fac ng\\u1ed3i suy ng\\u1eabm, anh t\\u1ef1 h\\u1ecfi m\\u00ecnh \\u0111\\u00e3 l\\u00e0m g\\u00ec t\\u1ed1t \\u0111\\u1eb9p trong cu\\u1ed9c \\u0111\\u1eddi \\u0111\\u1ec3 x\\u1ee9ng \\u0111\\u00e1ng c\\u00f3 \\u0111\\u01b0\\u1ee3c em b\\u00ean c\\u1ea1nh. Em mang \\u0111\\u1ebfn cho anh th\\u1ee9 \\u00e1nh s\\u00e1ng nh\\u1eb9 nh\\u00e0ng nh\\u01b0ng ng\\u1eadp tr\\u00e0n h\\u01a1i \\u1ea5m, xoa d\\u1ecbu m\\u1ecdi gi\\u00f4ng b\\u00e3o sau nh\\u1eefng ng\\u00e0y d\\u00e0i m\\u1ecfi m\\u1ec7t.\\r\\n                T\\u1eebng c\\u00e1i \\u00f4m si\\u1ebft ch\\u1eb7t, t\\u1eebng n\\u1ee5 c\\u01b0\\u1eddi l\\u1ea5p l\\u00e1nh c\\u1ee7a em \\u0111\\u00e3 tr\\u1edf th\\u00e0nh m\\u1ed9t ph\\u1ea7n thi\\u1ebft y\\u1ebfu trong h\\u01a1i th\\u1edf anh h\\u1eb1ng ng\\u00e0y. C\\u1ea3m \\u01a1n em v\\u00ec \\u0111\\u00e3 d\\u1ecbu d\\u00e0ng, \\u0111\\u00e3 l\\u1eafng nghe, \\u0111\\u00e3 c\\u00f9ng anh \\u0111i qua nh\\u1eefng cung b\\u1eadc x\\u00fac c\\u1ea3m tuy\\u1ec7t di\\u1ec7u nh\\u1ea5t.\\r\\n                Y\\u00eau em kh\\u00f4ng ch\\u1ec9 l\\u00e0 l\\u1eddi n\\u00f3i \\u0111\\u1ea7u m\\u00f4i, \\u0111\\u00f3 l\\u00e0 h\\u00e0nh tr\\u00ecnh n\\u1ed7 l\\u1ef1c \\u0111\\u1ec3 tr\\u1edf th\\u00e0nh m\\u1ed9t \\u0111i\\u1ec3m t\\u1ef1a v\\u1eefng v\\u00e0ng nh\\u1ea5t, mang l\\u1ea1i h\\u1ea1nh ph\\u00fac th\\u1ef1c s\\u1ef1 cho em m\\u00e3i m\\u00e3i v\\u1ec1 sau.\",\"letter.closing\":\"Y\\u00eau em v\\u00f4 \\u0111i\\u1ec1u ki\\u1ec7n\",\"letter.signature\":\"Anh c\\u1ee7a Em\",\"anniversary.start_date\":\"2024-05-01\"}', NULL, 'published', '2027-12-09 06:22:38', '2026-07-17 06:22:38', '2026-07-19 06:37:29');
INSERT INTO `landing_pages` (`id`, `user_id`, `template_id`, `title`, `slug`, `data`, `domain`, `status`, `expires_at`, `created_at`, `updated_at`) VALUES ('26', '5', '13', 'Đếm ngày yêu', 'dem-ngay-yeu-6a5c7551902b8', '{\"hero.page_title\":\"\\u0110\\u1ebfm Ng\\u00e0y Ch\\u00fang Ta \\u0110\\u00e3 B\\u00ean Nhau\",\"hero.title\":\"Ch\\u00fang Ta \\u0110\\u00e3 B\\u00ean Nhau\",\"hero.subtitle\":\"M\\u1ed7i ng\\u00e0y b\\u00ean nhau \\u0111\\u1ec1u l\\u00e0 m\\u00f3n qu\\u00e0 \\u0111\\u1eb9p nh\\u1ea5t.\",\"couple.groom_image\":\"https:\\/\\/i.pinimg.com\\/236x\\/d7\\/18\\/bb\\/d718bba37a543596f271fa1dafdd3001.jpg\",\"couple.groom_name\":\"Groom \\ud83d\\udc51\",\"couple.bride_image\":\"https:\\/\\/i.pinimg.com\\/1200x\\/04\\/4a\\/78\\/044a78f85cfd05892a4381f0d7d0a477.jpg\",\"couple.bride_name\":\"Bride \\ud83c\\udf38\",\"quote.content\":\"\\\"T\\u00ecnh y\\u00eau kh\\u00f4ng ph\\u1ea3i l\\u00e0 t\\u00ecm ki\\u1ebfm m\\u1ed9t ai \\u0111\\u00f3 ho\\u00e0n h\\u1ea3o, m\\u00e0 l\\u00e0 h\\u1ecdc c\\u00e1ch nh\\u00ecn th\\u1ea5y nh\\u1eefng \\u0111i\\u1ec1u tuy\\u1ec7t v\\u1eddi t\\u1eeb m\\u1ed9t ng\\u01b0\\u1eddi kh\\u00f4ng ho\\u00e0n h\\u1ea3o.\\\"\",\"timeline.title\":\"H\\u00e0nh Tr\\u00ecnh T\\u00ecnh Y\\u00eau\",\"timeline.items.0.date\":\"14.02.2024\",\"timeline.items.0.title\":\"\\u2764\\ufe0f L\\u1ea7n \\u0111\\u1ea7u g\\u1eb7p nhau\",\"timeline.items.0.desc\":\"Gi\\u1eefa d\\u00f2ng \\u0111\\u1eddi t\\u1ea5p n\\u1eadp, \\u00e1nh m\\u1eaft ta \\u0111\\u00e3 v\\u00f4 t\\u00ecnh ch\\u1ea1m nhau t\\u1ea1i m\\u1ed9t qu\\u00e1n c\\u00e0 ph\\u00ea nh\\u1ecf th\\u01a1m m\\u00f9i \\u1ea5m c\\u00fang.\",\"timeline.items.1.date\":\"08.03.2024\",\"timeline.items.1.title\":\"\\ud83c\\udf38 Bu\\u1ed5i h\\u1eb9n \\u0111\\u1ea7u ti\\u00ean\",\"timeline.items.1.desc\":\"M\\u1ed9t t\\u1ed1i m\\u01b0a l\\u1ea5t ph\\u1ea5t l\\u00e3ng m\\u1ea1n, ch\\u00fang ta \\u0111\\u00e3 tr\\u00f2 chuy\\u1ec7n h\\u00e0ng gi\\u1edd v\\u1ec1 \\u01b0\\u1edbc m\\u01a1, s\\u1edf th\\u00edch v\\u00e0 nh\\u1eadn ra t\\u00e2m h\\u1ed3n \\u0111\\u1ed3ng \\u0111i\\u1ec7u.\",\"timeline.items.2.date\":\"01.05.2024\",\"timeline.items.2.title\":\"\\ud83d\\udc95 Ch\\u00ednh th\\u1ee9c y\\u00eau\",\"timeline.items.2.desc\":\"L\\u1eddi t\\u1ecf t\\u00ecnh ng\\u01b0\\u1ee3ng ng\\u00f9ng c\\u00f9ng b\\u00f3 h\\u1ed3ng th\\u1eafm. Ng\\u00e0y em kh\\u1ebd g\\u1eadt \\u0111\\u1ea7u \\u0111\\u1ed3ng \\u00fd tr\\u1edf th\\u00e0nh m\\u1ea3nh gh\\u00e9p ho\\u00e0n h\\u1ea3o.\",\"timeline.items.3.date\":\"15.08.2024\",\"timeline.items.3.title\":\"\\u2708\\ufe0f Chuy\\u1ebfn \\u0111i \\u0111\\u1ea7u ti\\u00ean\",\"timeline.items.3.desc\":\"H\\u00e0nh tr\\u00ecnh kh\\u00e1m ph\\u00e1 th\\u00e0nh ph\\u1ed1 bi\\u1ec3n r\\u1ef1c r\\u1ee1 n\\u1eafng v\\u00e0ng. C\\u00f9ng ng\\u1eafm b\\u00ecnh minh v\\u00e0 h\\u1ee9a s\\u1ebd \\u0111i kh\\u1eafp th\\u1ebf gian.\",\"timeline.items.4.date\":\"10.10.2024\",\"timeline.items.4.title\":\"\\ud83c\\udf82 Sinh nh\\u1eadt c\\u00f9ng nhau\",\"timeline.items.4.desc\":\"B\\u1eefa ti\\u1ec7c sinh nh\\u1eadt \\u1ea5m \\u00e1p ch\\u1ec9 c\\u00f3 hai ng\\u01b0\\u1eddi. C\\u00f9ng nguy\\u1ec7n c\\u1ea7u d\\u01b0\\u1edbi \\u00e1nh n\\u1ebfn lung linh.\",\"timeline.items.5.date\":\"T\\u01b0\\u01a1ng lai\",\"timeline.items.5.title\":\"\\ud83d\\udc8d M\\u00e3i m\\u00e3i v\\u1ec1 sau\",\"timeline.items.5.desc\":\"Nh\\u1eefng trang s\\u00e1ch cu\\u1ed9c \\u0111\\u1eddi v\\u1eabn \\u0111ang ti\\u1ebfp t\\u1ee5c \\u0111\\u01b0\\u1ee3c vi\\u1ebft n\\u00ean b\\u1edfi t\\u00ecnh c\\u1ea3m n\\u1ed3ng n\\u00e0n c\\u1ee7a hai ta.\",\"gallery.title\":\"Kho\\u1ea3nh Kh\\u1eafc K\\u1ef7 Ni\\u1ec7m\",\"gallery.images.0\":\"https:\\/\\/images.unsplash.com\\/photo-1518199266791-5375a83190b7?auto=format&fit=crop&q=80&w=600\",\"gallery.images.1\":\"https:\\/\\/images.unsplash.com\\/photo-1515934751635-c81c6bc9a2d8?auto=format&fit=crop&q=80&w=600\",\"gallery.images.2\":\"https:\\/\\/images.unsplash.com\\/photo-1510154221590-ff63e90a136f?auto=format&fit=crop&q=80&w=600\",\"letter.title\":\"Th\\u01b0 G\\u1eedi Ng\\u01b0\\u1eddi Th\\u01b0\\u01a1ng\",\"letter.greeting\":\"Th\\u01b0\\u01a1ng g\\u1eedi Em y\\u00eau,\",\"letter.content\":\"Nhi\\u1ec1u l\\u00fac ng\\u1ed3i suy ng\\u1eabm, anh t\\u1ef1 h\\u1ecfi m\\u00ecnh \\u0111\\u00e3 l\\u00e0m g\\u00ec t\\u1ed1t \\u0111\\u1eb9p trong cu\\u1ed9c \\u0111\\u1eddi \\u0111\\u1ec3 x\\u1ee9ng \\u0111\\u00e1ng c\\u00f3 \\u0111\\u01b0\\u1ee3c em b\\u00ean c\\u1ea1nh. Em mang \\u0111\\u1ebfn cho anh th\\u1ee9 \\u00e1nh s\\u00e1ng nh\\u1eb9 nh\\u00e0ng nh\\u01b0ng ng\\u1eadp tr\\u00e0n h\\u01a1i \\u1ea5m, xoa d\\u1ecbu m\\u1ecdi gi\\u00f4ng b\\u00e3o sau nh\\u1eefng ng\\u00e0y d\\u00e0i m\\u1ecfi m\\u1ec7t.\\r\\n                T\\u1eebng c\\u00e1i \\u00f4m si\\u1ebft ch\\u1eb7t, t\\u1eebng n\\u1ee5 c\\u01b0\\u1eddi l\\u1ea5p l\\u00e1nh c\\u1ee7a em \\u0111\\u00e3 tr\\u1edf th\\u00e0nh m\\u1ed9t ph\\u1ea7n thi\\u1ebft y\\u1ebfu trong h\\u01a1i th\\u1edf anh h\\u1eb1ng ng\\u00e0y. C\\u1ea3m \\u01a1n em v\\u00ec \\u0111\\u00e3 d\\u1ecbu d\\u00e0ng, \\u0111\\u00e3 l\\u1eafng nghe, \\u0111\\u00e3 c\\u00f9ng anh \\u0111i qua nh\\u1eefng cung b\\u1eadc x\\u00fac c\\u1ea3m tuy\\u1ec7t di\\u1ec7u nh\\u1ea5t.\\r\\n                Y\\u00eau em kh\\u00f4ng ch\\u1ec9 l\\u00e0 l\\u1eddi n\\u00f3i \\u0111\\u1ea7u m\\u00f4i, \\u0111\\u00f3 l\\u00e0 h\\u00e0nh tr\\u00ecnh n\\u1ed7 l\\u1ef1c \\u0111\\u1ec3 tr\\u1edf th\\u00e0nh m\\u1ed9t \\u0111i\\u1ec3m t\\u1ef1a v\\u1eefng v\\u00e0ng nh\\u1ea5t, mang l\\u1ea1i h\\u1ea1nh ph\\u00fac th\\u1ef1c s\\u1ef1 cho em m\\u00e3i m\\u00e3i v\\u1ec1 sau.\",\"letter.closing\":\"Y\\u00eau em v\\u00f4 \\u0111i\\u1ec1u ki\\u1ec7n\",\"letter.signature\":\"Anh c\\u1ee7a Em\",\"anniversary.start_date\":\"2024-05-01\"}', NULL, 'draft', '2026-08-18 06:57:21', '2026-07-19 06:57:21', '2026-07-19 06:57:21');
INSERT INTO `landing_pages` (`id`, `user_id`, `template_id`, `title`, `slug`, `data`, `domain`, `status`, `expires_at`, `created_at`, `updated_at`) VALUES ('27', '5', '11', 'Giới thiệu doanh nghiệp', 'gioi-thieu-doanh-nghiep-6a5c77528a18b', '{\"site.title\":\"OriginD - T\\u1ea1o Website Ch\\u1ec9 Trong 5 Ph\\u00fat\",\"header.logo_text\":\"OriginD\",\"menu.about\":\"#about\",\"menu.features\":\"#features\",\"menu.contact\":\"#contact\",\"hero.title\":\"T\\u1ea1o website chuy\\u00ean nghi\\u1ec7pch\\u1ec9 trong 5 ph\\u00fat\",\"hero.subtitle\":\"OriginD - N\\u1ec1n t\\u1ea3ng t\\u1ea1o website nhanh ch\\u00f3ng, \\u0111\\u1eb9p m\\u1eaft v\\u00e0 ho\\u00e0n to\\u00e0n mi\\u1ec5n ph\\u00ed\",\"hero.cta_button\":\"https:\\/\\/www.facebook.com\\/NguyenHaiDang2005.FB\",\"hero.note\":\"Kh\\u00f4ng c\\u1ea7n th\\u1ebb t\\u00edn d\\u1ee5ng \\u2022 Kh\\u00f4ng c\\u1ea7n bi\\u1ebft code\",\"about.title\":\"OriginD l\\u00e0 g\\u00ec?\",\"about.description\":\"OriginD l\\u00e0 n\\u1ec1n t\\u1ea3ng gi\\u00fap b\\u1ea1n t\\u1ea1o website chuy\\u00ean nghi\\u1ec7p ch\\u1ec9 trong 5 ph\\u00fat m\\u00e0 kh\\u00f4ng c\\u1ea7n bi\\u1ebft l\\u1eadp tr\\u00ecnh. \\r\\n            V\\u1edbi h\\u00e0ng tr\\u0103m m\\u1eabu \\u0111\\u1eb9p hi\\u1ec7n \\u0111\\u1ea1i, b\\u1ea1n ch\\u1ec9 c\\u1ea7n ch\\u1ecdn v\\u00e0 ch\\u1ec9nh s\\u1eeda theo \\u00fd mu\\u1ed1n.\",\"about.benefit1\":\"Ho\\u00e0n to\\u00e0n mi\\u1ec5n ph\\u00ed\",\"about.benefit2\":\"Responsive tr\\u00ean m\\u1ecdi thi\\u1ebft b\\u1ecb\",\"about.benefit3\":\"T\\u00f9y ch\\u1ec9nh d\\u1ec5 d\\u00e0ng\",\"about.image\":\"https:\\/\\/i.imgur.com\\/IZ7lAzD.png\",\"features.title\":\"T\\u1ea1i sao n\\u00ean ch\\u1ecdn OriginD?\",\"features.1.title\":\"Si\\u00eau nhanh\",\"features.1.desc\":\"Ch\\u1ec9 m\\u1ea5t 5 ph\\u00fat \\u0111\\u1ec3 c\\u00f3 m\\u1ed9t website ho\\u00e0n ch\\u1ec9nh\",\"features.2.title\":\"Thi\\u1ebft k\\u1ebf \\u0111\\u1eb9p\",\"features.2.desc\":\"H\\u00e0ng tr\\u0103m m\\u1eabu giao di\\u1ec7n hi\\u1ec7n \\u0111\\u1ea1i, chuy\\u00ean nghi\\u1ec7p\",\"features.3.title\":\"Mi\\u1ec5n ph\\u00ed 100%\",\"features.3.desc\":\"S\\u1eed d\\u1ee5ng tr\\u1ecdn \\u0111\\u1eddi m\\u00e0 kh\\u00f4ng m\\u1ea5t b\\u1ea5t k\\u1ef3 chi ph\\u00ed n\\u00e0o\",\"footer.logo_text\":\"OriginD\",\"footer.slogan\":\"T\\u1ea1o website nhanh - \\u0110\\u1eb9p - Mi\\u1ec5n ph\\u00ed\",\"footer.email\":\"contact.origind@gmail.com\",\"footer.phone\":\"0866 984 097\"}', NULL, 'draft', '2026-08-18 07:05:54', '2026-07-19 07:05:54', '2026-07-19 07:05:54');
INSERT INTO `landing_pages` (`id`, `user_id`, `template_id`, `title`, `slug`, `data`, `domain`, `status`, `expires_at`, `created_at`, `updated_at`) VALUES ('29', '1', '20', 'Website gara chuyên dụng', 'website-gara-chuyen-dung-6a61f13044bb6', '{\"gallery.img1\":\"https:\\/\\/images.unsplash.com\\/photo-1526726538690-5cbf956ae2fd?q=80&w=900&auto=format&fit=crop\",\"gallery.img2\":\"https:\\/\\/images.unsplash.com\\/photo-1580273916550-e323be2ae537?q=80&w=900&auto=format&fit=crop\",\"gallery.img3\":\"https:\\/\\/images.unsplash.com\\/photo-1555215695-3004980ad54e?q=80&w=900&auto=format&fit=crop\",\"contact.badge\":\"Th\\u00f4ng Tin Li\\u00ean H\\u1ec7DAG\",\"contact.title_p1\":\"K\\u1ebft N\\u1ed1i Tr\\u1ef1c Ti\\u1ebfp V\\u1edbiDAG\",\"contact.title_p2\":\"BMW GaraDAG\",\"contact.description\":\"DAGQu\\u00fd kh\\u00e1ch h\\u00e0ng c\\u00f3 nhu c\\u1ea7u t\\u01b0 v\\u1ea5n k\\u1ef9 thu\\u1eadt ho\\u1eb7c \\u0111\\u01b0a xe \\u0111\\u1ebfn x\\u01b0\\u1edfng vui l\\u00f2ng gh\\u00e9 tr\\u1ef1c ti\\u1ebfp \\u0111\\u1ecba ch\\u1ec9 b\\u00ean d\\u01b0\\u1edbi.\",\"contact.address_label\":\"\\u0110\\u1ecba ch\\u1ec9 x\\u01b0\\u1edfng d\\u1ecbch v\\u1ee5DAG\",\"contact.address_val\":\"DAGS\\u1ed1 68 \\u0110\\u01b0\\u1eddng \\u0110\\u1ea1i L\\u1ed9 BMW, Ph\\u01b0\\u1eddng An Ph\\u00fa, TP. Th\\u1ee7 \\u0110\\u1ee9c, TP.HCM\",\"header.brand_name\":\"DAGBMW GARA\",\"header.brand_slogan\":\"DAGExclusive Service\",\"header.nav1\":\"#hero\",\"header.nav2\":\"#about\",\"header.nav3\":\"#services\",\"header.nav4\":\"#gallery\",\"header.nav5\":\"#contact\",\"header.phone\":\"tel:0866984097\",\"hero.slide_1\":\"https:\\/\\/images.unsplash.com\\/photo-1555215695-3004980ad54e?q=80&w=2000&auto=format&fit=crop\",\"hero.slide_2\":\"https:\\/\\/i.ibb.co\\/spGDb26G\\/bm.png\",\"hero.slide_3\":\"https:\\/\\/images.unsplash.com\\/photo-1580273916550-e323be2ae537?q=80&w=2000&auto=format&fit=crop\",\"hero.badge\":\"DAGTrung T\\u00e2m Ch\\u0103m S\\u00f3c & S\\u1eeda Ch\\u1eefa BMW Ti\\u00eau Chu\\u1ea9n \\u0110\\u1ee9c\",\"hero.title_p1\":\"DAG\\u0110\\u1eb3ng C\\u1ea5p Chuy\\u00ean S\\u00e2u Cho\",\"hero.title_p2\":\"DAGX\\u1ebf Y\\u00eau\",\"hero.subtitle\":\"DAGH\\u1ec7 th\\u1ed1ng ch\\u1ea9n \\u0111o\\u00e1n ch\\u00ednh h\\u00e3ng ISTA, ph\\u1ee5 t\\u00f9ng nh\\u1eadp kh\\u1ea9u \\u0110\\u1ee9c 100% c\\u00f9ng \\u0111\\u1ed9i ng\\u0169 chuy\\u00ean gia gi\\u00e0u kinh nghi\\u1ec7m t\\u1ed1i \\u01b0u v\\u1eadn h\\u00e0nh cho x\\u1ebf c\\u01b0ng c\\u1ee7a b\\u1ea1n.\",\"hero.btn1_link\":\"#services\",\"hero.btn2_link\":\"#contact\",\"card.title\":\"DAGH\\u1ec7 Th\\u1ed1ng Ch\\u1ea9n \\u0110o\\u00e1n\",\"card.version\":\"DAGISTA v4.4\",\"card.stat1_name\":\"DAG\\u0110\\u1ed9ng c\\u01a1 TwinPower Turbo\",\"card.stat1_val\":\"DAGT\\u1ed1i \\u01afu 99%\",\"card.stat2_name\":\"DAGH\\u1ec7 Th\\u1ed1ng \\u0110i\\u1ec7n & H\\u1ed9p S\\u1ed1\",\"card.stat2_val\":\"DAGChu\\u1ea9n X\\u00e1c 100%\",\"card.footnote\":\"DAGB\\u1ea3o h\\u00e0nh \\u0111i\\u1ec7n t\\u1eed to\\u00e0n qu\\u1ed1c\",\"about.img1\":\"https:\\/\\/images.unsplash.com\\/photo-1617814076367-b759c7d7e738?q=80&w=800&auto=format&fit=crop\",\"about.img2\":\"https:\\/\\/images.unsplash.com\\/photo-1503376780353-7e6692767b70?q=80&w=800&auto=format&fit=crop\",\"about.badge\":\"DAGV\\u1ec1 BMW Gara\",\"about.title_p1\":\"DAGChuy\\u00ean Gia S\\u1eeda Ch\\u1eefa & N\\u00e2ng C\\u1ea5p\",\"about.title_p2\":\"DAGXe H\\u01a1i Cao C\\u1ea5p\",\"about.description\":\"DAGDAGBMW Gara \\u0111\\u01b0\\u1ee3c x\\u00e2y d\\u1ef1ng chuy\\u00ean bi\\u1ec7t \\u0111\\u1ec3 ph\\u1ee5c v\\u1ee5 d\\u00f2ng xe sang tr\\u1ecdng \\u0111\\u1ebfn t\\u1eeb \\u0110\\u1ee9c. Ch\\u00fang t\\u00f4i mang \\u0111\\u1ebfn ti\\u00eau chu\\u1ea9n k\\u1ef9 thu\\u1eadt \\u0111\\u1ec9nh cao, t\\u01b0\\u01a1ng \\u0111\\u01b0\\u01a1ng trung t\\u00e2m \\u1ee7y quy\\u1ec1n ch\\u00ednh h\\u00e3ng nh\\u01b0ng t\\u1ed1i \\u01b0u chi ph\\u00ed v\\u00e0 th\\u1eddi gian cho kh\\u00e1ch h\\u00e0ng.\",\"about.feature1\":\"DAGPh\\u1ea7n m\\u1ec1m ISTA ch\\u00ednh h\\u00e3ng\",\"about.feature2\":\"DAGPh\\u1ee5 t\\u00f9ng chu\\u1ea9n \\u0110\\u1ee9c 100%\",\"services.badge\":\"DAGD\\u1ecbch V\\u1ee5 C\\u1ed1t L\\u00f5i\",\"services.title_p1\":\"DAGGi\\u1ea3i Ph\\u00e1p To\\u00e0n Di\\u1ec7n Cho\",\"services.title_p2\":\"M\\u1ecdi D\\u00f2ng Xe\",\"services.subtitle\":\"DAGC\\u00e1c h\\u1ea1ng m\\u1ee5c d\\u1ecbch v\\u1ee5 chuy\\u00ean s\\u00e2u \\u0111\\u01b0\\u1ee3c th\\u1ef1c hi\\u1ec7n b\\u1edfi \\u0111\\u1ed9i ng\\u0169 k\\u1ef9 thu\\u1eadt vi\\u00ean tay ngh\\u1ec1 cao.\",\"services.s1_title\":\"DAGB\\u1ea3o D\\u01b0\\u1ee1ng \\u0110\\u1ecbnh K\\u1ef3\",\"services.s1_desc\":\"DAGThay nh\\u1edbt \\u0111\\u1ed9ng c\\u01a1, l\\u1ecdc nh\\u1edbt, ki\\u1ec3m tra h\\u1ec7 th\\u1ed1ng phanh, g\\u1ea7m v\\u00e0 reset h\\u1ec7 th\\u1ed1ng b\\u1ea3o d\\u01b0\\u1ee1ng \\u0111i\\u1ec7n t\\u1eed.\",\"services.s2_title\":\"DAGCh\\u1ea9n \\u0110o\\u00e1n & S\\u1eeda Ch\\u1eefa \\u0110i\\u1ec7n\",\"services.s2_desc\":\"DAGS\\u1eed d\\u1ee5ng thi\\u1ebft b\\u1ecb ph\\u1ea7n m\\u1ec1m chuy\\u00ean h\\u00e3ng ISTA l\\u1eadp tr\\u00ecnh, coding h\\u1ed9p \\u0111i\\u1ec1u khi\\u1ec3n, x\\u1eed l\\u00fd tri\\u1ec7t \\u0111\\u1ec3 l\\u1ed7i xe.\",\"services.s3_title\":\"DAG\\u0110\\u1ea1i Tu \\u0110\\u1ed9ng C\\u01a1 & H\\u1ed9p S\\u1ed1\",\"services.s3_desc\":\"DAG\\u0110\\u1ea1i tu chuy\\u00ean s\\u00e2u \\u0111\\u1ed9ng c\\u01a1, x\\u1eed l\\u00fd r\\u00f2 r\\u1ec9 d\\u1ea7u, b\\u1ea3o d\\u01b0\\u1ee1ng h\\u1ed9p s\\u1ed1 t\\u1ef1 \\u0111\\u1ed9ng ti\\u00eau chu\\u1ea9n k\\u1ef9 thu\\u1eadt cao.\",\"services.s4_title\":\"DAG\\u0110\\u1ed3ng S\\u01a1n & S\\u01a1n Cao C\\u1ea5p\",\"services.s4_desc\":\"DAGPh\\u00f2ng s\\u01a1n s\\u1ea5y h\\u1ea5p ti\\u00eau chu\\u1ea9n, pha m\\u00e0u vi t\\u00ednh ch\\u00ednh x\\u00e1c 100%, ph\\u1ee5c h\\u1ed3i form xe nguy\\u00ean b\\u1ea3n.\",\"services.s5_title\":\"DAGN\\u00e2ng C\\u1ea5p Options (Retrofit)\",\"services.s5_desc\":\"DAGN\\u00e2ng c\\u1ea5p camera 360, c\\u1eeda h\\u00edt, \\u0111\\u00e8n Laser, \\u00e2m thanh cao c\\u1ea5p, bodykit M-Sport ch\\u00ednh h\\u00e3ng.\",\"services.s6_title\":\"DAGCh\\u0103m S\\u00f3c & Detailing\",\"services.s6_desc\":\"DAGDAGPh\\u1ee7 Ceramic b\\u1ea3o v\\u1ec7 s\\u01a1n, d\\u00e1n phim c\\u00e1ch nhi\\u1ec7t cao c\\u1ea5p, v\\u1ec7 sinh khoang m\\u00e1y v\\u00e0 n\\u1ed9i th\\u1ea5t chuy\\u00ean s\\u00e2u.\",\"gallery.badge\":\"DAGTh\\u01b0 Vi\\u1ec7n H\\u00ecnh \\u1ea2nh\",\"gallery.title_p1\":\"DAGKh\\u00f4ng Gian X\\u01b0\\u1edfng &\",\"gallery.title_p2\":\"DAGD\\u1ef1 \\u00c1n Th\\u1ef1c T\\u1ebf\",\"gallery.subtitle\":\"DAGDAGTr\\u1ea3i nghi\\u1ec7m kh\\u00f4ng gian x\\u01b0\\u1edfng d\\u1ecbch v\\u1ee5 hi\\u1ec7n \\u0111\\u1ea1i v\\u00e0 nh\\u1eefng si\\u00eau ph\\u1ea9m BMW ho\\u00e0n thi\\u1ec7n t\\u1ea1i gara.\"}', NULL, 'published', NULL, '2026-07-23 10:47:12', '2026-07-23 10:47:18');
