INSERT INTO `template_fields` (`id`, `template_id`, `label`, `key`, `type`, `default_value`, `required`, `sort_order`, `created_at`, `updated_at`, `html_tag`, `attribute`, `placeholder`, `options`) VALUES ('186', '13', 'Nội dung thư tình', 'letter.content', 'textarea', '[\"Nhi\\u1ec1u l\\u00fac ng\\u1ed3i suy ng\\u1eabm, anh t\\u1ef1 h\\u1ecfi m\\u00ecnh \\u0111\\u00e3 l\\u00e0m g\\u00ec t\\u1ed1t \\u0111\\u1eb9p trong cu\\u1ed9c \\u0111\\u1eddi \\u0111\\u1ec3 x\\u1ee9ng \\u0111\\u00e1ng c\\u00f3 \\u0111\\u01b0\\u1ee3c em b\\u00ean c\\u1ea1nh. Em mang \\u0111\\u1ebfn cho anh th\\u1ee9 \\u00e1nh s\\u00e1ng nh\\u1eb9 nh\\u00e0ng nh\\u01b0ng ng\\u1eadp tr\\u00e0n h\\u01a1i \\u1ea5m, xoa d\\u1ecbu m\\u1ecdi gi\\u00f4ng b\\u00e3o sau nh\\u1eefng ng\\u00e0y d\\u00e0i m\\u1ecfi m\\u1ec7t.\\r\\n                T\\u1eebng c\\u00e1i \\u00f4m si\\u1ebft ch\\u1eb7t, t\\u1eebng n\\u1ee5 c\\u01b0\\u1eddi l\\u1ea5p l\\u00e1nh c\\u1ee7a em \\u0111\\u00e3 tr\\u1edf th\\u00e0nh m\\u1ed9t ph\\u1ea7n thi\\u1ebft y\\u1ebfu trong h\\u01a1i th\\u1edf anh h\\u1eb1ng ng\\u00e0y. C\\u1ea3m \\u01a1n em v\\u00ec \\u0111\\u00e3 d\\u1ecbu d\\u00e0ng, \\u0111\\u00e3 l\\u1eafng nghe, \\u0111\\u00e3 c\\u00f9ng anh \\u0111i qua nh\\u1eefng cung b\\u1eadc x\\u00fac c\\u1ea3m tuy\\u1ec7t di\\u1ec7u nh\\u1ea5t.\\r\\n                Y\\u00eau em kh\\u00f4ng ch\\u1ec9 l\\u00e0 l\\u1eddi n\\u00f3i \\u0111\\u1ea7u m\\u00f4i, \\u0111\\u00f3 l\\u00e0 h\\u00e0nh tr\\u00ecnh n\\u1ed7 l\\u1ef1c \\u0111\\u1ec3 tr\\u1edf th\\u00e0nh m\\u1ed9t \\u0111i\\u1ec3m t\\u1ef1a v\\u1eefng v\\u00e0ng nh\\u1ea5t, mang l\\u1ea1i h\\u1ea1nh ph\\u00fac th\\u1ef1c s\\u1ef1 cho em m\\u00e3i m\\u00e3i v\\u1ec1 sau.\"]', '0', '0', '2026-07-16 11:09:33', '2026-07-16 11:09:33', 'div', 'text', NULL, NULL);
